INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 16, 'theory', 'Quiz: QEMU/KVM practice and observability');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 0, 'What should you check first before launching QEMU with KVM?', '["The amount of RAM", "The vmx or svm flags and the availability of /dev/kvm", "The shell version", "The network speed"]', 1, 'virt-host-validate checks the processor, kernel modules, control groups, and the IOMMU all at once.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 1, 'What does perf kvm stat show?', '["A list of the guest''s files", "The image size", "The reasons for guest exits and the share of time spent on each", "The processor temperature"]', 2, 'Usually the leaders are processor halts, external interrupts, MSR writes, and EPT violations.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 2, 'A lot of IO_INSTRUCTION in the report: what does it point to?', '["The network is too fast", "The guest is powered off", "The disk is encrypted", "Somewhere a device is emulated through ports instead of using paravirtual ones"]', 3, 'Replacing emulation with virtio is the most common way to cut exits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 3, 'What does qemu-img commit do?', '["Creates a snapshot of the machine state", "Merges a layer into the base image", "Encrypts the image", "Copies the image over the network"]', 1, 'To flatten the whole chain into one file, use the convert command.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 16, 4, 'What should you check first when the guest''s network is slow?', '["Whether the device is paravirtual, whether vhost is on, and whether there are enough queues", "The color of the terminal", "The swap size", "Only the guest kernel version"]', 0, 'Card emulation and single-threaded queue handling are the most common causes.');
